package com.example.FitnessChallengeApp_Test.controller;
import com.example.FitnessChallengeApp_Test.model.*;import com.example.FitnessChallengeApp_Test.service.*;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;
@Controller public class WorkoutLogController {private final WorkoutLogService workoutLogService;private final ChallengeService challengeService;
 public WorkoutLogController(WorkoutLogService w,ChallengeService c){workoutLogService=w;challengeService=c;}
 private void options(Model m){m.addAttribute("challenges",challengeService.getAllChallenges().stream().filter(Challenge::isActive).toList());m.addAttribute("intensityLevels",workoutLogService.getIntensityLevels());m.addAttribute("pageTitle","Log Workout");}
 @GetMapping("/log-workout") public String form(Model m){m.addAttribute("workoutLog",new WorkoutLog());options(m);return "log-workout";}
 @PostMapping("/log-workout") public String submit(@Valid @ModelAttribute("workoutLog") WorkoutLog log,BindingResult result,Model m){Challenge c=challengeService.getChallengeById(log.getChallengeId());if(log.getChallengeId()!=null&&(c==null||!c.isActive()))result.rejectValue("challengeId","invalid","Please select an active challenge");if(!workoutLogService.getIntensityLevels().contains(log.getIntensityLevel()))result.rejectValue("intensityLevel","invalid","Please select a valid intensity level");if(result.hasErrors()){options(m);return "log-workout";}workoutLogService.addLog(log,c);return "redirect:/workout-logs";}
 @GetMapping("/workout-logs") public String logs(Model m){m.addAttribute("workoutLogs",workoutLogService.getAllLogs());m.addAttribute("pageTitle","Workout Logs");return "workout-logs";}}
